    byKind: Record<NodeKind, number>;
    byLanguage: Record<Language, number>;
  };
  edges: {
    total: number;
    byKind: Record<EdgeKind, number>;
    resolved: number;
    unresolved: number;
  };
  vectors: number;
}

export interface Path {
  nodes: Node[];
  edges: Edge[];
  length: number;
}

export interface ExportedGraph {
  version: number;
  exportedAt: number;
  config: CodeGraphConfig;
  stats: GraphStats;
  nodes: Node[];
  edges: Edge[];
}
