## Tree-sitter Extraction Queries

These `.scm` files define what to extract from each language.

**File: `src/extraction/queries/typescript.scm`**

```scheme
; ============================================================
; TYPESCRIPT/JAVASCRIPT EXTRACTION QUERIES
; ============================================================

; Functions
(function_declaration
  name: (identifier) @function.name
  parameters: (formal_parameters) @function.params
  return_type: (type_annotation)? @function.return_type
  body: (statement_block) @function.body
) @function.definition

; Arrow functions assigned to variables
(lexical_declaration
  (variable_declarator
    name: (identifier) @function.name
    value: (arrow_function
      parameters: (formal_parameters) @function.params
      return_type: (type_annotation)? @function.return_type
      body: (_) @function.body
    )
  )
) @function.definition

; Classes
(class_declaration
  name: (type_identifier) @class.name
  (class_heritage
    (extends_clause
      value: (identifier) @class.extends
    )?
    (implements_clause
      (type_identifier) @class.implements
    )*
  )?
  body: (class_body) @class.body
) @class.definition

; Methods
(method_definition
  name: (property_identifier) @method.name
  parameters: (formal_parameters) @method.params
  return_type: (type_annotation)? @method.return_type
  body: (statement_block) @method.body
) @method.definition

; Interfaces
(interface_declaration
  name: (type_identifier) @interface.name
  (extends_type_clause
    (type_identifier) @interface.extends
  )?
  body: (interface_body) @interface.body
) @interface.definition

; Type aliases
(type_alias_declaration
  name: (type_identifier) @type.name
  value: (_) @type.value
) @type.definition

; Imports
(import_statement
  (import_clause
    (identifier)? @import.default
    (named_imports
      (import_specifier
        name: (identifier) @import.named
        alias: (identifier)? @import.alias
      )*
    )?
  )?
  source: (string) @import.source
) @import.statement

; Exports
(export_statement
  (export_clause
    (export_specifier
      name: (identifier) @export.name
    )*
  )?
  declaration: (_)? @export.declaration
) @export.statement

; Function calls
(call_expression
  function: [
    (identifier) @call.function
    (member_expression
      object: (_) @call.object
      property: (property_identifier) @call.method
    )
  ]
  arguments: (arguments) @call.args
) @call.expression

; Variable declarations (const/let with significant values)
(lexical_declaration
  (variable_declarator
    name: (identifier) @variable.name
    value: (_) @variable.value
  )
) @variable.declaration

; JSDoc comments
(comment) @comment
