      const code = `
        export function processPayment(amount: number): Promise<Receipt> {
          return stripe.charge(amount);
        }
      `;
      const result = await extract(code, 'typescript');

      expect(result.nodes).toContainEqual(expect.objectContaining({
        kind: 'function',
        name: 'processPayment',
