#!/usr/bin/env node
const { execSync } = require('child_process');
const fs = require('fs');
const path = require('path');
const readline = require('readline');

const PKG_PATH = path.join(__dirname, 'package.json');
const pkg = JSON.parse(fs.readFileSync(PKG_PATH, 'utf-8'));
const [major, minor, patch] = pkg.version.split('.').map(Number);

const rl = readline.createInterface({ input: process.stdin, output: process.stdout });

function ask(question) {
  return new Promise((resolve) => rl.question(question, resolve));
}

async function main() {
  console.log(`\nCurrent version: ${pkg.version}\n`);
  console.log('  1) patch  -> ' + `${major}.${minor}.${patch + 1}`);
  console.log('  2) minor  -> ' + `${major}.${minor + 1}.0`);
  console.log('  3) major  -> ' + `${major + 1}.0.0`);
  console.log('');

  const choice = await ask('Bump version (1/2/3): ');

  let bump;
  switch (choice.trim()) {
    case '1': bump = 'patch'; break;
    case '2': bump = 'minor'; break;
    case '3': bump = 'major'; break;
    default:
      console.log('Invalid choice. Exiting.');
      rl.close();
      process.exit(1);
  }

  // Bump version in package.json
  execSync(`npm version ${bump} --no-git-tag-version`, { stdio: 'inherit' });

  const updated = JSON.parse(fs.readFileSync(PKG_PATH, 'utf-8'));
  console.log(`\nVersion bumped to ${updated.version}`);

  const confirm = await ask(`Publish ${updated.name}@${updated.version} to npm? (y/n): `);
  if (confirm.trim().toLowerCase() !== 'y') {
    console.log('Aborted.');
    rl.close();
    process.exit(0);
  }

  // Build and publish
  console.log('\nBuilding...');
  execSync('npm run build', { stdio: 'inherit' });

  console.log('\nPublishing...');
  execSync('npm publish --access public', { stdio: 'inherit' });

  console.log(`\nPublished ${updated.name}@${updated.version}`);
  rl.close();
}

main().catch((err) => {
  console.error(err);
  rl.close();
  process.exit(1);
});

#!/usr/bin/env node
/**
 * Patches tree-sitter-dart to use NAPI bindings compatible with tree-sitter 0.22+
 *
 * tree-sitter-dart v1.0.0 ships with NAN-style bindings that are incompatible
 * with tree-sitter 0.22+ which expects NAPI-style bindings with type-tagged
 * externals. This script rewrites the binding files and rebuilds.
 */
const { writeFileSync, existsSync } = require('fs');
const { join } = require('path');
const { execSync } = require('child_process');

const DART_DIR = join(__dirname, '..', 'node_modules', 'tree-sitter-dart');

if (!existsSync(DART_DIR)) {
  // tree-sitter-dart not installed, skip
  process.exit(0);
}

// Check if already patched (look for NAPI-style binding)
const bindingPath = join(DART_DIR, 'bindings', 'node', 'binding.cc');
const { readFileSync } = require('fs');
try {
  const existing = readFileSync(bindingPath, 'utf8');
  if (existing.includes('napi.h')) {
    // Already patched, check if build exists
    const buildPath = join(DART_DIR, 'build', 'Release', 'tree_sitter_dart_binding.node');
    if (existsSync(buildPath)) {
      console.log('tree-sitter-dart: already patched and built.');
      process.exit(0);
    }
    // Patched but not built, fall through to rebuild
  }
} catch {
  // Can't read, continue with patch
}

console.log('Patching tree-sitter-dart for NAPI compatibility...');

// Write NAPI-compatible binding.cc
const bindingCC = `#include <napi.h>

typedef struct TSLanguage TSLanguage;

extern "C" TSLanguage *tree_sitter_dart();

// "tree-sitter", "language" hashed with BLAKE2
const napi_type_tag LANGUAGE_TYPE_TAG = {
    0x8AF2E5212AD58ABF, 0xD5006CAD83ABBA16
};

Napi::Object Init(Napi::Env env, Napi::Object exports) {
    exports["name"] = Napi::String::New(env, "dart");
    auto language = Napi::External<TSLanguage>::New(env, tree_sitter_dart());
    language.TypeTag(&LANGUAGE_TYPE_TAG);
    exports["language"] = language;
    return exports;
}

NODE_API_MODULE(tree_sitter_dart_binding, Init)
`;
writeFileSync(bindingPath, bindingCC);

// Write NAPI-compatible binding.gyp
const bindingGyp = `{
  "targets": [
    {
      "target_name": "tree_sitter_dart_binding",
      "dependencies": [
        "<!(node -p \\"require('node-addon-api').targets\\"):node_addon_api_except"
      ],
      "include_dirs": [
        "src"
      ],
      "sources": [
        "src/parser.c",
        "bindings/node/binding.cc",
        "src/scanner.c"
      ],
      "conditions": [
        ["OS!='win'", {
          "cflags_c": [
            "-std=c99"
          ]
        }, {
          "cflags_c": [
            "/std:c11",
            "/utf-8"
          ]
        }]
      ]
    }
  ]
}
`;
writeFileSync(join(DART_DIR, 'binding.gyp'), bindingGyp);

// Rebuild native module
try {
  execSync('npx node-gyp rebuild', {
    cwd: DART_DIR,
    stdio: 'pipe',
    timeout: 120000,
  });
  console.log('tree-sitter-dart: patched and rebuilt successfully.');
} catch (error) {
  console.error('Warning: Failed to rebuild tree-sitter-dart native module.');
  console.error('Dart language support may not work.');
  if (process.env.DEBUG) {
    console.error(error.stderr?.toString());
  }
}

#!/usr/bin/env node
/**
 * Postinstall script - downloads the embedding model to ~/.codegraph/models
 * This runs after `npm install` or `npx @colbymchenry/codegraph`
 */
const { existsSync, mkdirSync } = require('fs');
const { join } = require('path');
const { homedir } = require('os');

const CODEGRAPH_DIR = join(homedir(), '.codegraph');
const MODELS_DIR = join(CODEGRAPH_DIR, 'models');
const MODEL_ID = 'nomic-ai/nomic-embed-text-v1.5';

async function downloadModel() {
  // Ensure directories exist
  if (!existsSync(CODEGRAPH_DIR)) {
    mkdirSync(CODEGRAPH_DIR, { recursive: true });
  }
  if (!existsSync(MODELS_DIR)) {
    mkdirSync(MODELS_DIR, { recursive: true });
  }

  // Check if model is already cached
  const modelCachePath = join(MODELS_DIR, MODEL_ID.replace('/', '/'));
  if (existsSync(modelCachePath)) {
    console.log('Embedding model already downloaded.');
    return;
  }

  console.log('Downloading embedding model (~130MB)...');
  console.log('This is a one-time download for semantic code search.\n');

  try {
    // Dynamic import for @xenova/transformers (ESM-only package)
    const { pipeline, env } = await import('@xenova/transformers');

    // Configure cache directory
    env.cacheDir = MODELS_DIR;

    // Download with progress
    await pipeline('feature-extraction', MODEL_ID, {
      progress_callback: (progress) => {
        if (progress.status === 'progress' && progress.file && progress.progress !== undefined) {
          const fileName = progress.file.split('/').pop();
          const percent = Math.round(progress.progress);
          process.stdout.write(`\rDownloading ${fileName}... ${percent}%   `);
        } else if (progress.status === 'done') {
          process.stdout.write('\n');
        }
      },
    });

    console.log('\nEmbedding model ready!');
  } catch (error) {
    // Don't fail the install if model download fails
    // User can still use codegraph without semantic search
    console.log('\nNote: Could not download embedding model.');
    console.log('Semantic search will download it on first use.');
    if (process.env.DEBUG) {
      console.error(error);
    }
  }
}

downloadModel().catch(() => {
  // Silent exit - don't break npm install
  process.exit(0);
});

#!/usr/bin/env node
/**
 * CodeGraph CLI
 *
 * Command-line interface for CodeGraph code intelligence.
 *
 * Usage:
 *   codegraph                    Run interactive installer (when no args)
 *   codegraph install            Run interactive installer
 *   codegraph init [path]        Initialize CodeGraph in a project
 *   codegraph uninit [path]      Remove CodeGraph from a project
 *   codegraph index [path]       Index all files in the project
 *   codegraph sync [path]        Sync changes since last index
 *   codegraph status [path]      Show index status
 *   codegraph query <search>     Search for symbols
 *   codegraph files [options]    Show project file structure
 *   codegraph context <task>     Build context for a task
 *   codegraph mark-dirty [path]  Mark project as needing sync (hooks)
 *   codegraph sync-if-dirty [path] Sync if marked dirty (hooks)
 *
 * Note: Git hooks have been removed. CodeGraph sync is triggered automatically
 * through codegraph's Claude Code hooks integration.
 */

import { Command } from 'commander';
import * as path from 'path';
import * as fs from 'fs';
import { spawn } from 'child_process';
import { getCodeGraphDir, findNearestCodeGraphRoot, isInitialized } from '../directory';
import { initSentry, captureException } from '../sentry';

// Lazy-load heavy modules (CodeGraph, runInstaller) to keep CLI startup fast.
async function loadCodeGraph(): Promise<typeof import('../index')> {
  try {
    return await import('../index');
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    console.error('\x1b[31m✗\x1b[0m Failed to load CodeGraph modules.');
    console.error(`\n  Node: ${process.version}  Platform: ${process.platform} ${process.arch}`);
    console.error(`\n  Error: ${msg}`);
    console.error('\n  Try reinstalling with: npm install -g @colbymchenry/codegraph\n');
    process.exit(1);
  }
}

type IndexProgress = import('../index').IndexProgress;

// Check if running with no arguments - run installer
// Read version for Sentry release tag
const pkgVersion = (() => {
  try {
    return JSON.parse(fs.readFileSync(path.join(__dirname, '..', '..', 'package.json'), 'utf-8')).version;
  } catch { return undefined; }
})();
initSentry({ processName: 'codegraph-cli', version: pkgVersion });

if (process.argv.length === 2) {
  import('../installer').then(({ runInstaller }) =>
    runInstaller()
  ).catch((err) => {
    captureException(err);
    console.error('Installation failed:', err instanceof Error ? err.message : String(err));
    process.exit(1);
  });
} else {
  // Normal CLI flow
  main();
}

process.on('uncaughtException', (error) => {
  captureException(error);
  console.error('[CodeGraph] Uncaught exception:', error);
});

process.on('unhandledRejection', (reason) => {
  captureException(reason);
  console.error('[CodeGraph] Unhandled rejection:', reason);
});

function main() {

const program = new Command();

// Version from package.json
const packageJson = JSON.parse(
  fs.readFileSync(path.join(__dirname, '..', '..', 'package.json'), 'utf-8')
);

// =============================================================================
// ANSI Color Helpers (avoid chalk ESM issues)
// =============================================================================

const colors = {
  reset: '\x1b[0m',
  bold: '\x1b[1m',
  dim: '\x1b[2m',
  red: '\x1b[31m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  cyan: '\x1b[36m',
  white: '\x1b[37m',
  gray: '\x1b[90m',
};

const chalk = {
  bold: (s: string) => `${colors.bold}${s}${colors.reset}`,
  dim: (s: string) => `${colors.dim}${s}${colors.reset}`,
  red: (s: string) => `${colors.red}${s}${colors.reset}`,
  green: (s: string) => `${colors.green}${s}${colors.reset}`,
  yellow: (s: string) => `${colors.yellow}${s}${colors.reset}`,
  blue: (s: string) => `${colors.blue}${s}${colors.reset}`,
  cyan: (s: string) => `${colors.cyan}${s}${colors.reset}`,
  white: (s: string) => `${colors.white}${s}${colors.reset}`,
  gray: (s: string) => `${colors.gray}${s}${colors.reset}`,
};

program
  .name('codegraph')
  .description('Code intelligence and knowledge graph for any codebase')
  .version(packageJson.version);

// =============================================================================
// Helper Functions
// =============================================================================

/**
 * Resolve project path from argument or current directory
 * Walks up parent directories to find nearest initialized CodeGraph project
 * (must have .codegraph/codegraph.db, not just .codegraph/lessons.db)
 */
function resolveProjectPath(pathArg?: string): string {
  const absolutePath = path.resolve(pathArg || process.cwd());

  // If exact path is initialized (has codegraph.db), use it
  if (isInitialized(absolutePath)) {
    return absolutePath;
  }

  // Walk up to find nearest parent with CodeGraph initialized
  // Note: findNearestCodeGraphRoot finds any .codegraph folder, but we need one with codegraph.db
  let current = absolutePath;
  const root = path.parse(current).root;

  while (current !== root) {
    const parent = path.dirname(current);
    if (parent === current) break;
    current = parent;

    if (isInitialized(current)) {
      return current;
    }
  }

  // Not found - return original path (will fail later with helpful error)
  return absolutePath;
}

/**
 * Format a number with commas
 */
function formatNumber(n: number): string {
  return n.toLocaleString();
}

/**
 * Format duration in milliseconds to human readable
 */
function formatDuration(ms: number): string {
  if (ms < 1000) {
    return `${ms}ms`;
  }
  const seconds = ms / 1000;
  if (seconds < 60) {
    return `${seconds.toFixed(1)}s`;
  }
  const minutes = Math.floor(seconds / 60);
  const remainingSeconds = seconds % 60;
  return `${minutes}m ${remainingSeconds.toFixed(0)}s`;
}

/**
 * Create a progress bar string
 */
function progressBar(current: number, total: number, width: number = 30): string {
  const percent = total > 0 ? current / total : 0;
  const filled = Math.round(width * percent);
  const empty = width - filled;
  const bar = chalk.green('█'.repeat(filled)) + chalk.gray('░'.repeat(empty));
  const percentStr = `${Math.round(percent * 100)}%`.padStart(4);
  return `${bar} ${percentStr}`;
}

/**
 * Print a progress update (overwrites current line)
 */
function printProgress(progress: IndexProgress): void {
  const phaseNames: Record<string, string> = {
    scanning: 'Scanning files',
    parsing: 'Parsing code',
    storing: 'Storing data',
    resolving: 'Resolving refs',
  };

  const phaseName = phaseNames[progress.phase] || progress.phase;
  const bar = progressBar(progress.current, progress.total);
  const file = progress.currentFile ? chalk.dim(` ${progress.currentFile}`) : '';

  // Clear line and print progress
  process.stdout.write(`\r${chalk.cyan(phaseName)}: ${bar}${file}`.padEnd(100));
}

/**
 * Print success message
 */
function success(message: string): void {
  console.log(chalk.green('✓') + ' ' + message);
}

/**
 * Print error message
 */
function error(message: string): void {
  console.error(chalk.red('✗') + ' ' + message);
}

/**
 * Print info message
 */
function info(message: string): void {
  console.log(chalk.blue('ℹ') + ' ' + message);
}

/**
 * Print warning message
 */
function warn(message: string): void {
  console.log(chalk.yellow('⚠') + ' ' + message);
}

// =============================================================================
// Commands
// =============================================================================

/**
 * codegraph init [path]
 */
program
  .command('init [path]')
  .description('Initialize CodeGraph in a project directory')
  .option('-i, --index', 'Run initial indexing after initialization')
  .action(async (pathArg: string | undefined, options: { index?: boolean }) => {
    const projectPath = resolveProjectPath(pathArg);

    console.log(chalk.bold('\nInitializing CodeGraph...\n'));

    try {
      // Check if already initialized
      if (isInitialized(projectPath)) {
        warn(`CodeGraph already initialized in ${projectPath}`);
        info('Use "codegraph index" to re-index or "codegraph sync" to update');
        return;
      }

      // Initialize
      const { default: CodeGraph } = await loadCodeGraph();
      const cg = await CodeGraph.init(projectPath, {
        index: false, // We'll handle indexing ourselves for progress
      });

      success(`Initialized CodeGraph in ${projectPath}`);
      info(`Created .codegraph/ directory`);

      // Run initial index if requested
      if (options.index) {
        console.log('\nIndexing project...\n');

        const result = await cg.indexAll({
          onProgress: printProgress,
        });

        // Clear progress line
        process.stdout.write('\r' + ' '.repeat(100) + '\r');

        if (result.success) {
          success(`Indexed ${formatNumber(result.filesIndexed)} files`);
          info(`Created ${formatNumber(result.nodesCreated)} nodes and ${formatNumber(result.edgesCreated)} edges`);
          info(`Completed in ${formatDuration(result.durationMs)}`);
        } else {
          warn(`Indexing completed with ${result.errors.length} errors`);
        }
      } else {
        info('Run "codegraph index" to index the project');
      }

      cg.destroy();
    } catch (err) {
      captureException(err);
      error(`Failed to initialize: ${err instanceof Error ? err.message : String(err)}`);
      process.exit(1);
    }
  });

/**
 * codegraph uninit [path]
 */
program
  .command('uninit [path]')
  .description('Remove CodeGraph from a project (deletes .codegraph/ directory)')
  .option('-f, --force', 'Skip confirmation prompt')
  .action(async (pathArg: string | undefined, options: { force?: boolean }) => {
    const projectPath = resolveProjectPath(pathArg);

    try {
      if (!isInitialized(projectPath)) {
        warn(`CodeGraph is not initialized in ${projectPath}`);
        return;
      }

      if (!options.force) {
        // Confirm with user
        const readline = await import('readline');
        const rl = readline.createInterface({ input: process.stdin, output: process.stdout });
        const answer = await new Promise<string>((resolve) => {
          rl.question(
            chalk.yellow('⚠ This will permanently delete all CodeGraph data. Continue? (y/N) '),
            resolve
          );
        });
        rl.close();

        if (answer.toLowerCase() !== 'y') {
          info('Cancelled');
          return;
        }
      }

      const { default: CodeGraph } = await loadCodeGraph();
      const cg = CodeGraph.openSync(projectPath);
      cg.uninitialize();

      success(`Removed CodeGraph from ${projectPath}`);
    } catch (err) {
      captureException(err);
      error(`Failed to uninitialize: ${err instanceof Error ? err.message : String(err)}`);
      process.exit(1);
    }
  });

/**
 * codegraph index [path]
 */
program
  .command('index [path]')
  .description('Index all files in the project')
  .option('-f, --force', 'Force full re-index even if already indexed')
  .option('-q, --quiet', 'Suppress progress output')
  .action(async (pathArg: string | undefined, options: { force?: boolean; quiet?: boolean }) => {
    const projectPath = resolveProjectPath(pathArg);

    try {
      if (!isInitialized(projectPath)) {
        error(`CodeGraph not initialized in ${projectPath}`);
        info('Run "codegraph init" first');
        process.exit(1);
      }

      const { default: CodeGraph } = await loadCodeGraph();
      const cg = await CodeGraph.open(projectPath);

      if (!options.quiet) {
        console.log(chalk.bold('\nIndexing project...\n'));
      }

      // Clear existing data if force
      if (options.force) {
        cg.clear();
        if (!options.quiet) {
          info('Cleared existing index');
        }
      }

      const result = await cg.indexAll({
        onProgress: options.quiet ? undefined : printProgress,
      });

      // Clear progress line
      if (!options.quiet) {
        process.stdout.write('\r' + ' '.repeat(100) + '\r');
      }

      if (result.success) {
        if (!options.quiet) {
          success(`Indexed ${formatNumber(result.filesIndexed)} files`);
          info(`Created ${formatNumber(result.nodesCreated)} nodes and ${formatNumber(result.edgesCreated)} edges`);
          info(`Completed in ${formatDuration(result.durationMs)}`);
        }
      } else {
        if (!options.quiet) {
          warn(`Indexing completed with ${result.errors.length} errors`);
          for (const err of result.errors.slice(0, 5)) {
            console.log(chalk.dim(`  - ${err.message}`));
          }
          if (result.errors.length > 5) {
            console.log(chalk.dim(`  ... and ${result.errors.length - 5} more`));
          }
        }
        process.exit(1);
      }

      cg.destroy();
    } catch (err) {
      captureException(err);
      error(`Failed to index: ${err instanceof Error ? err.message : String(err)}`);
      process.exit(1);
    }
  });

/**
 * codegraph sync [path]
 */
program
  .command('sync [path]')
  .description('Sync changes since last index')
  .option('-q, --quiet', 'Suppress output (for git hooks)')
  .action(async (pathArg: string | undefined, options: { quiet?: boolean }) => {
    const projectPath = resolveProjectPath(pathArg);

    try {
      if (!isInitialized(projectPath)) {
        if (!options.quiet) {
          error(`CodeGraph not initialized in ${projectPath}`);
        }
        process.exit(1);
      }

      const { default: CodeGraph } = await loadCodeGraph();
      const cg = await CodeGraph.open(projectPath);

      const result = await cg.sync({
        onProgress: options.quiet ? undefined : printProgress,
      });

      // Clear progress line
      if (!options.quiet) {
        process.stdout.write('\r' + ' '.repeat(100) + '\r');
      }

      const totalChanges = result.filesAdded + result.filesModified + result.filesRemoved;

      if (!options.quiet) {
        if (totalChanges === 0) {
          success('Already up to date');
        } else {
          success(`Synced ${formatNumber(totalChanges)} changed files`);
          if (result.filesAdded > 0) {
            info(`  Added: ${result.filesAdded}`);
          }
          if (result.filesModified > 0) {
            info(`  Modified: ${result.filesModified}`);
          }
          if (result.filesRemoved > 0) {
            info(`  Removed: ${result.filesRemoved}`);
          }
          info(`Updated ${formatNumber(result.nodesUpdated)} nodes in ${formatDuration(result.durationMs)}`);
        }
      }

      cg.destroy();
    } catch (err) {
      captureException(err);
      if (!options.quiet) {
        error(`Failed to sync: ${err instanceof Error ? err.message : String(err)}`);
      }
      process.exit(1);
    }
  });

