import { InstallLocation } from './prompts';
import {
  CLAUDE_MD_TEMPLATE,
  CODEGRAPH_SECTION_START,
  CODEGRAPH_SECTION_END,
} from './claude-md-template';

/**
 * Get the path to the Claude config directory
 */
function getClaudeConfigDir(location: InstallLocation): string {
  if (location === 'global') {
    return path.join(os.homedir(), '.claude');
  }
  return path.join(process.cwd(), '.claude');
}

/**
 * Get the path to the claude.json file
 * - Global: ~/.claude.json (root level)
 * - Local: ./.claude.json (project root)
 */
function getClaudeJsonPath(location: InstallLocation): string {
  if (location === 'global') {
    return path.join(os.homedir(), '.claude.json');
  }
  return path.join(process.cwd(), '.claude.json');
}

/**
 * Get the path to the settings.json file
 * - Global: ~/.claude/settings.json
 * - Local: ./.claude/settings.json
 */
function getSettingsJsonPath(location: InstallLocation): string {
  const configDir = getClaudeConfigDir(location);
  return path.join(configDir, 'settings.json');
}

/**
 * Read a JSON file, returning an empty object if it doesn't exist.
 * Distinguishes between missing files (returns {}) and corrupted
 * files (logs warning, returns {}).
 */
function readJsonFile(filePath: string): Record<string, any> {
  if (!fs.existsSync(filePath)) {
    return {};
  }
  try {
    const content = fs.readFileSync(filePath, 'utf-8');
    return JSON.parse(content);
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    console.warn(`  Warning: Could not parse ${path.basename(filePath)}: ${msg}`);
    console.warn(`  A backup will be created before overwriting.`);
    // Create a backup of the corrupted file
    try {
      const backupPath = filePath + '.backup';
      fs.copyFileSync(filePath, backupPath);
    } catch { /* ignore backup failure */ }
    return {};
  }
}

/**
 * Write a file atomically by writing to a temp file then renaming.
 * Prevents corruption if the process crashes mid-write.
 */
function atomicWriteFileSync(filePath: string, content: string): void {
  const dir = path.dirname(filePath);
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }
  const tmpPath = filePath + '.tmp.' + process.pid;
  try {
    fs.writeFileSync(tmpPath, content);
    fs.renameSync(tmpPath, filePath);
  } catch (err) {
    // Clean up temp file on failure
    try { fs.unlinkSync(tmpPath); } catch { /* ignore */ }
    throw err;
  }
}

/**
 * Write a JSON file, creating parent directories if needed
 */
function writeJsonFile(filePath: string, data: Record<string, any>): void {
  atomicWriteFileSync(filePath, JSON.stringify(data, null, 2) + '\n');
}

/**
 * Get the MCP server configuration
 */
function getMcpServerConfig(): Record<string, any> {
  return {
    type: 'stdio',
    command: 'codegraph',
    args: ['serve', '--mcp'],
  };
}

/**
 * Write the MCP server configuration to claude.json
 */
export function writeMcpConfig(location: InstallLocation): void {
  const claudeJsonPath = getClaudeJsonPath(location);
  const config = readJsonFile(claudeJsonPath);

  // Ensure mcpServers object exists
  if (!config.mcpServers) {
    config.mcpServers = {};
  }

  // Add or update codegraph server
  config.mcpServers.codegraph = getMcpServerConfig();

  writeJsonFile(claudeJsonPath, config);
}

/**
 * Get the list of permissions for CodeGraph tools
 */
function getCodeGraphPermissions(): string[] {
  return [
    'mcp__codegraph__codegraph_search',
    'mcp__codegraph__codegraph_context',
    'mcp__codegraph__codegraph_callers',
    'mcp__codegraph__codegraph_callees',
    'mcp__codegraph__codegraph_impact',
    'mcp__codegraph__codegraph_node',
    'mcp__codegraph__codegraph_status',
  ];
}

/**
 * Write permissions to settings.json
 */
export function writePermissions(location: InstallLocation): void {
  const settingsPath = getSettingsJsonPath(location);
  const settings = readJsonFile(settingsPath);

  // Ensure permissions object exists
  if (!settings.permissions) {
    settings.permissions = {};
  }

  // Ensure allow array exists
  if (!Array.isArray(settings.permissions.allow)) {
    settings.permissions.allow = [];
  }

  // Add CodeGraph permissions (avoiding duplicates)
  const codegraphPermissions = getCodeGraphPermissions();
  for (const permission of codegraphPermissions) {
    if (!settings.permissions.allow.includes(permission)) {
      settings.permissions.allow.push(permission);
    }
  }

  writeJsonFile(settingsPath, settings);
}

/**
 * Check if MCP config already exists for CodeGraph
 */
export function hasMcpConfig(location: InstallLocation): boolean {
  const claudeJsonPath = getClaudeJsonPath(location);
  const config = readJsonFile(claudeJsonPath);
  return !!config.mcpServers?.codegraph;
}

/**
 * Check if permissions already exist for CodeGraph
 */
export function hasPermissions(location: InstallLocation): boolean {
  const settingsPath = getSettingsJsonPath(location);
  const settings = readJsonFile(settingsPath);
  const permissions = settings.permissions?.allow;
  if (!Array.isArray(permissions)) {
    return false;
  }
  // Check if at least one CodeGraph permission exists
  return permissions.some((p: string) => p.startsWith('mcp__codegraph__'));
}

// =============================================================================
// Hooks Configuration
// =============================================================================

/**
 * Get the hooks configuration for Claude Code auto-sync.
 *
 * PostToolUse(Edit|Write) → mark-dirty (async, non-blocking)
 * Stop → sync-if-dirty (sync, ensures fresh index before next user turn)
 */
function getHooksConfig(): Record<string, any> {
  const command = 'codegraph';

  return {
    PostToolUse: [
      {
        matcher: 'Edit|Write',
        hooks: [
          {
            type: 'command',
            command: `${command} mark-dirty`,
            async: true,
          },
        ],
      },
    ],
    Stop: [
      {
        matcher: '.*',
        hooks: [
          {
            type: 'command',
            command: `${command} sync-if-dirty`,
          },
        ],
      },
    ],
  };
}

/**
 * Check if Claude Code hooks already exist for CodeGraph
 */
export function hasHooks(location: InstallLocation): boolean {
  const settingsPath = getSettingsJsonPath(location);
  const settings = readJsonFile(settingsPath);
  const hooks = settings.hooks;
  if (!hooks) return false;

  // Check if any hook command references codegraph
  const json = JSON.stringify(hooks);
  return json.includes('codegraph mark-dirty') || json.includes('codegraph sync-if-dirty');
}

/**
 * Write Claude Code hooks to settings.json for auto-sync.
 * Merges with existing hooks, deduplicating any previous codegraph entries.
 */
export function writeHooks(location: InstallLocation): void {
  const settingsPath = getSettingsJsonPath(location);
  const settings = readJsonFile(settingsPath);

  if (!settings.hooks) {
    settings.hooks = {};
  }

  const newHooks = getHooksConfig();

  // For each hook event (PostToolUse, Stop), merge with existing entries
  for (const [event, newEntries] of Object.entries(newHooks)) {
    if (!Array.isArray(settings.hooks[event])) {
      settings.hooks[event] = [];
    }

    // Remove any existing codegraph entries for this event
    settings.hooks[event] = (settings.hooks[event] as any[]).filter((entry: any) => {
      // Keep entries that don't reference codegraph
      const entryJson = JSON.stringify(entry);
      return !entryJson.includes('codegraph mark-dirty') && !entryJson.includes('codegraph sync-if-dirty');
    });

    // Add new codegraph entries
    settings.hooks[event].push(...(newEntries as any[]));
  }

  writeJsonFile(settingsPath, settings);
}

/**
 * Get the path to CLAUDE.md
 * - Global: ~/.claude/CLAUDE.md
 * - Local: ./.claude/CLAUDE.md
 */
function getClaudeMdPath(location: InstallLocation): string {
  const configDir = getClaudeConfigDir(location);
  return path.join(configDir, 'CLAUDE.md');
}

/**
 * Check if CLAUDE.md has CodeGraph section
 */
export function hasClaudeMdSection(location: InstallLocation): boolean {
  const claudeMdPath = getClaudeMdPath(location);
  try {
    if (fs.existsSync(claudeMdPath)) {
      const content = fs.readFileSync(claudeMdPath, 'utf-8');
      return content.includes(CODEGRAPH_SECTION_START) || content.includes('## CodeGraph');
    }
  } catch {
    // Ignore errors
  }
  return false;
}

/**
 * Write or update CLAUDE.md with CodeGraph instructions
 *
 * If the file exists and has a CodeGraph section (marked or unmarked),
 * it will be replaced. Otherwise, the template is appended.
 */
export function writeClaudeMd(location: InstallLocation): { created: boolean; updated: boolean } {
  const claudeMdPath = getClaudeMdPath(location);
  const configDir = getClaudeConfigDir(location);

  // Ensure directory exists
  if (!fs.existsSync(configDir)) {
    fs.mkdirSync(configDir, { recursive: true });
  }

  // Check if file exists
  if (!fs.existsSync(claudeMdPath)) {
    // Create new file with just the CodeGraph section
    atomicWriteFileSync(claudeMdPath, CLAUDE_MD_TEMPLATE + '\n');
    return { created: true, updated: false };
  }

  // Read existing content
  let content = fs.readFileSync(claudeMdPath, 'utf-8');

  // Check for marked section (from previous installer)
  if (content.includes(CODEGRAPH_SECTION_START)) {
    // Replace the marked section
    const startIdx = content.indexOf(CODEGRAPH_SECTION_START);
    const endIdx = content.indexOf(CODEGRAPH_SECTION_END);

    if (endIdx > startIdx) {
      // Replace existing marked section
      const before = content.substring(0, startIdx);
      const after = content.substring(endIdx + CODEGRAPH_SECTION_END.length);
      content = before + CLAUDE_MD_TEMPLATE + after;
      atomicWriteFileSync(claudeMdPath, content);
      return { created: false, updated: true };
    }
  }

  // Check for unmarked "## CodeGraph" section (from manual setup)
  const codegraphHeaderRegex = /\n## CodeGraph\n/;
  const match = content.match(codegraphHeaderRegex);

  if (match && match.index !== undefined) {
    // Find the end of the CodeGraph section (next h2 header or end of file)
    // Use negative lookahead (?!#) to match "## X" but not "### X"
    const sectionStart = match.index;
    const afterSection = content.substring(sectionStart + 1);
    const nextHeaderMatch = afterSection.match(/\n## (?!#)/);

    let sectionEnd: number;
    if (nextHeaderMatch && nextHeaderMatch.index !== undefined) {
      sectionEnd = sectionStart + 1 + nextHeaderMatch.index;
    } else {
      sectionEnd = content.length;
    }

    // Replace the section
    const before = content.substring(0, sectionStart);
    const after = content.substring(sectionEnd);
    content = before + '\n' + CLAUDE_MD_TEMPLATE + after;
    atomicWriteFileSync(claudeMdPath, content);
    return { created: false, updated: true };
  }

  // No existing section, append to end
  content = content.trimEnd() + '\n\n' + CLAUDE_MD_TEMPLATE + '\n';
  atomicWriteFileSync(claudeMdPath, content);
  return { created: false, updated: false };
}

/**
 * CodeGraph Interactive Installer
 *
 * Provides a beautiful interactive CLI experience for setting up CodeGraph
 * with Claude Code.
 */

import { execSync } from 'child_process';
import { showBanner, showNextSteps, success, error, info, chalk } from './banner';
import { promptInstallLocation, promptAutoAllow, InstallLocation } from './prompts';
import { writeMcpConfig, writePermissions, writeClaudeMd, writeHooks, hasMcpConfig, hasPermissions, hasHooks } from './config-writer';

/**
 * Format a number with commas
 */
function formatNumber(n: number): string {
  return n.toLocaleString();
}

/**
 * Run the interactive installer
 */
export async function runInstaller(): Promise<void> {
  // Show the banner
  showBanner();

  try {
    // Step 1: Install codegraph globally.
    // Always run npm install -g — we can't use `command -v codegraph` to check
    // because npx puts a temporary binary in PATH that vanishes when npx exits.
    console.log(chalk.dim('  Installing codegraph globally...'));
    try {
      execSync('npm install -g @colbymchenry/codegraph', { stdio: 'pipe' });
      success('Installed codegraph command globally');
    } catch {
      info('Could not install globally (permission denied)');
      info('Try: sudo npm install -g @colbymchenry/codegraph');
    }
    console.log();

    // Step 2: Ask for installation location
    const location = await promptInstallLocation();
    console.log();

    // Step 3: Write MCP configuration (always uses npx for reliability)
    const alreadyHasMcp = hasMcpConfig(location);
    writeMcpConfig(location);

    if (alreadyHasMcp) {
      success(`Updated MCP server in ${location === 'global' ? '~/.claude.json' : './.claude.json'}`);
    } else {
      success(`Added MCP server to ${location === 'global' ? '~/.claude.json' : './.claude.json'}`);
    }

    // Step 4: Ask about auto-allow permissions
    const autoAllow = await promptAutoAllow();
    console.log();

    if (autoAllow) {
      const alreadyHasPerms = hasPermissions(location);
      writePermissions(location);

      if (alreadyHasPerms) {
        success(`Updated permissions in ${location === 'global' ? '~/.claude/settings.json' : './.claude/settings.json'}`);
      } else {
        success(`Added permissions to ${location === 'global' ? '~/.claude/settings.json' : './.claude/settings.json'}`);
      }
    }

    // Step 5: Write auto-sync hooks
    const alreadyHasHooks = hasHooks(location);
    writeHooks(location);

    if (alreadyHasHooks) {
      success(`Updated auto-sync hooks in ${location === 'global' ? '~/.claude/settings.json' : './.claude/settings.json'}`);
    } else {
      success(`Added auto-sync hooks to ${location === 'global' ? '~/.claude/settings.json' : './.claude/settings.json'}`);
    }

    // Step 6: Write CLAUDE.md instructions
    const claudeMdResult = writeClaudeMd(location);
    const claudeMdPath = location === 'global' ? '~/.claude/CLAUDE.md' : './.claude/CLAUDE.md';

    if (claudeMdResult.created) {
      success(`Created ${claudeMdPath} with CodeGraph instructions`);
    } else if (claudeMdResult.updated) {
      success(`Updated CodeGraph section in ${claudeMdPath}`);
    } else {
      success(`Added CodeGraph instructions to ${claudeMdPath}`);
    }

    // Step 7: For local install, initialize the project
    if (location === 'local') {
      await initializeLocalProject();
    }

    // Show next steps
    showNextSteps(location);
  } catch (err) {
    console.log();
    if (err instanceof Error && err.message.includes('readline was closed')) {
      // User cancelled with Ctrl+C
      console.log(chalk.dim('  Installation cancelled.'));
    } else {
      error(`Installation failed: ${err instanceof Error ? err.message : String(err)}`);
    }
    process.exit(1);
  }
}

/**
 * Initialize CodeGraph in the current project (for local installs)
 */
async function initializeLocalProject(): Promise<void> {
  const projectPath = process.cwd();

  // Lazy-load CodeGraph (requires native modules)
  let CodeGraph: typeof import('../index').default;
  try {
    CodeGraph = (await import('../index')).default;
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    error(`Could not load native modules: ${msg}`);
    info('Skipping project initialization. You can run "codegraph init -i" later.');
    info('If this persists, try a Node.js LTS version (20 or 22).');
    return;
  }

  // Check if already initialized
  if (CodeGraph.isInitialized(projectPath)) {
    info('CodeGraph already initialized in this project');
    return;
  }

  console.log();
  console.log(chalk.dim('  Initializing CodeGraph in current project...'));

  // Initialize CodeGraph
  const cg = await CodeGraph.init(projectPath);
  success('Created .codegraph/ directory');

  // Index the project
  const result = await cg.indexAll({
    onProgress: (progress) => {
      // Simple progress indicator
      const phaseNames: Record<string, string> = {
        scanning: 'Scanning files',
        parsing: 'Parsing code',
        storing: 'Storing data',
        resolving: 'Resolving refs',
      };
      const phaseName = phaseNames[progress.phase] || progress.phase;
      const percent = progress.total > 0 ? Math.round((progress.current / progress.total) * 100) : 0;
      process.stdout.write(`\r  ${chalk.dim(phaseName)}... ${percent}%   `);
    },
  });

  // Clear progress line
  process.stdout.write('\r' + ' '.repeat(50) + '\r');

  if (result.success) {
    success(`Indexed ${formatNumber(result.filesIndexed)} files (${formatNumber(result.nodesCreated)} symbols)`);
  } else {
    success(`Indexed ${formatNumber(result.filesIndexed)} files with ${result.errors.length} warnings`);
  }

  cg.close();
}

// Export for use in CLI
export { InstallLocation };

/**
 * User prompts for the CodeGraph installer
 * Uses built-in readline to avoid ESM issues with inquirer
 */

import * as readline from 'readline';
import { chalk } from './banner';

export type InstallLocation = 'global' | 'local';

/**
 * Create a readline interface for prompts
 */
function createInterface(): readline.Interface {
  return readline.createInterface({
    input: process.stdin,
    output: process.stdout,
  });
}

/**
 * Prompt the user with a question and return their answer
 */
function prompt(rl: readline.Interface, question: string): Promise<string> {
  return new Promise((resolve) => {
    rl.question(question, (answer) => {
      resolve(answer.trim());
    });
  });
}

/**
 * Prompt for installation location (global or local)
 */
export async function promptInstallLocation(): Promise<InstallLocation> {
  const rl = createInterface();

  console.log(chalk.bold('  Where would you like to install?'));
  console.log();
  console.log('  1) Global (~/.claude) - available in all projects');
  console.log('  2) Local (./.claude) - this project only');
  console.log();

  const answer = await prompt(rl, '  Choice [1]: ');
  rl.close();

  // Default to '1' if empty, parse the answer
  const choice = answer === '' ? '1' : answer;

  if (choice === '2') {
    return 'local';
  }
  return 'global';
}

/**
 * Prompt for auto-allow permissions
 */
export async function promptAutoAllow(): Promise<boolean> {
  const rl = createInterface();

  console.log();
  console.log(chalk.bold('  Auto-allow CodeGraph commands?') + chalk.dim(' (Skips permission prompts)'));
  console.log();
  console.log('  1) Yes - auto-approve all codegraph_* tools');
  console.log('  2) No - ask for permission each time');
  console.log();

  const answer = await prompt(rl, '  Choice [1]: ');
  rl.close();

  // Default to '1' if empty
  const choice = answer === '' ? '1' : answer;

  return choice !== '2';
}

/**
 * Prompt for confirmation (yes/no)
 */
export async function promptConfirm(message: string, defaultYes: boolean = true): Promise<boolean> {
  const rl = createInterface();

  const defaultStr = defaultYes ? 'Y/n' : 'y/N';
  const answer = await prompt(rl, `  ${message} [${defaultStr}]: `);
  rl.close();

  if (answer === '') {
    return defaultYes;
  }

  return answer.toLowerCase().startsWith('y');
}

/**
 * CodeGraph MCP Server
 *
 * Model Context Protocol server that exposes CodeGraph functionality
 * as tools for AI assistants like Claude.
 *
 * @module mcp
 *
 * @example
 * ```typescript
 * import { MCPServer } from 'codegraph';
 *
 * const server = new MCPServer('/path/to/project');
 * await server.start();
 * ```
 */

import * as path from 'path';
import CodeGraph, { findNearestCodeGraphRoot } from '../index';
import { StdioTransport, JsonRpcRequest, JsonRpcNotification, ErrorCodes } from './transport';
import { tools, ToolHandler } from './tools';
import { initSentry, captureException } from '../sentry';

initSentry({ processName: 'codegraph-mcp' });

/**
 * Convert a file:// URI to a filesystem path.
 * Handles URL encoding and Windows drive letter paths.
 */
function fileUriToPath(uri: string): string {
  try {
    const url = new URL(uri);
    let filePath = decodeURIComponent(url.pathname);
    // On Windows, file:///C:/path produces pathname /C:/path — strip leading /
    if (process.platform === 'win32' && /^\/[a-zA-Z]:/.test(filePath)) {
      filePath = filePath.slice(1);
    }
    return path.resolve(filePath);
  } catch {
    // Fallback for non-standard URIs
    return uri.replace(/^file:\/\/\/?/, '');
  }
}

/**
 * MCP Server Info
 */
const SERVER_INFO = {
  name: 'codegraph',
  version: '0.1.0',
};

/**
 * MCP Protocol Version
 */
const PROTOCOL_VERSION = '2024-11-05';

/**
 * MCP Server for CodeGraph
 *
 * Implements the Model Context Protocol to expose CodeGraph
 * functionality as tools that can be called by AI assistants.
 */
export class MCPServer {
  private transport: StdioTransport;
  private cg: CodeGraph | null = null;
  private toolHandler: ToolHandler;
  private projectPath: string | null;

  constructor(projectPath?: string) {
    this.projectPath = projectPath || null;
    this.transport = new StdioTransport();
    // Create ToolHandler eagerly — cross-project queries work even without a default project
    this.toolHandler = new ToolHandler(null);
  }

  /**
   * Start the MCP server
   *
   * Note: CodeGraph initialization is deferred until the initialize request
   * is received, which includes the rootUri from the client.
   */
  async start(): Promise<void> {
    // Start listening for messages immediately - don't check initialization yet
    // We'll get the project path from the initialize request's rootUri
    this.transport.start(this.handleMessage.bind(this));

    // Keep the process running
    process.on('SIGINT', () => this.stop());
    process.on('SIGTERM', () => this.stop());

    // When the parent process (Claude Code) exits, stdin closes.
    // Detect this and shut down gracefully to prevent orphaned processes.
    process.stdin.on('end', () => this.stop());
    process.stdin.on('close', () => this.stop());
  }

  /**
   * Try to initialize CodeGraph for the default project.
   *
   * Walks up parent directories to find the nearest .codegraph/ folder,
   * similar to how git finds .git/ directories.
   *
   * If initialization fails, the error is recorded but the server continues
   * to work — cross-project queries and retries on subsequent tool calls
   * are still possible.
   */
  private async tryInitializeDefault(projectPath: string): Promise<void> {
    // Walk up parent directories to find nearest .codegraph/
    const resolvedRoot = findNearestCodeGraphRoot(projectPath);

    if (!resolvedRoot) {
      this.projectPath = projectPath;
      return;
    }

    this.projectPath = resolvedRoot;

    try {
      this.cg = await CodeGraph.open(resolvedRoot);
      this.toolHandler.setDefaultCodeGraph(this.cg);
    } catch (err) {
      captureException(err);
    }
  }

  /**
   * Retry initialization of the default project if it previously failed.
   * Called lazily on tool calls that need the default project.
   */
  private retryInitIfNeeded(): void {
    // Already initialized successfully
    if (this.toolHandler.hasDefaultCodeGraph()) return;
    // No project path to retry with
    if (!this.projectPath) return;

    const resolvedRoot = findNearestCodeGraphRoot(this.projectPath);
    if (!resolvedRoot) return;

    try {
      this.cg = CodeGraph.openSync(resolvedRoot);
      this.projectPath = resolvedRoot;
      this.toolHandler.setDefaultCodeGraph(this.cg);
    } catch {
      // Still failing — will retry on next tool call
    }
  }

  /**
   * Stop the server
   */
  stop(): void {
    // Close all cached cross-project connections first
    this.toolHandler.closeAll();
    // Close the main CodeGraph instance
    if (this.cg) {
      this.cg.close();
      this.cg = null;
    }
    this.transport.stop();
    process.exit(0);
  }

  /**
   * Handle incoming JSON-RPC messages
   */
  private async handleMessage(message: JsonRpcRequest | JsonRpcNotification): Promise<void> {
    // Check if it's a request (has id) or notification (no id)
    const isRequest = 'id' in message;

    switch (message.method) {
      case 'initialize':
        if (isRequest) {
          await this.handleInitialize(message as JsonRpcRequest);
        }
        break;

      case 'initialized':
        // Notification that client has finished initialization
        // No action needed - the client is ready
        break;

      case 'tools/list':
        if (isRequest) {
          await this.handleToolsList(message as JsonRpcRequest);
        }
        break;

      case 'tools/call':
        if (isRequest) {
          await this.handleToolsCall(message as JsonRpcRequest);
        }
        break;

      case 'ping':
        if (isRequest) {
          this.transport.sendResult((message as JsonRpcRequest).id, {});
        }
        break;

      default:
        if (isRequest) {
          this.transport.sendError(
            (message as JsonRpcRequest).id,
            ErrorCodes.MethodNotFound,
            `Method not found: ${message.method}`
          );
        }
    }
  }

  /**
   * Handle initialize request
   */
  private async handleInitialize(request: JsonRpcRequest): Promise<void> {
    const params = request.params as {
      rootUri?: string;
      workspaceFolders?: Array<{ uri: string; name: string }>;
    } | undefined;

    // Extract project path from rootUri or workspaceFolders
    let projectPath = this.projectPath;

    if (params?.rootUri) {
      projectPath = fileUriToPath(params.rootUri);
    } else if (params?.workspaceFolders?.[0]?.uri) {
      projectPath = fileUriToPath(params.workspaceFolders[0].uri);
    }

    // Fall back to current working directory if no path provided
    if (!projectPath) {
      projectPath = process.cwd();
    }

    // Try to initialize the default project (non-fatal if it fails)
    await this.tryInitializeDefault(projectPath);

    // We accept the client's protocol version but respond with our supported version
    this.transport.sendResult(request.id, {
      protocolVersion: PROTOCOL_VERSION,
      capabilities: {
        tools: {},
      },
      serverInfo: SERVER_INFO,
    });
  }

  /**
   * Handle tools/list request
   */
  private async handleToolsList(request: JsonRpcRequest): Promise<void> {
    this.transport.sendResult(request.id, {
      tools: tools,
    });
  }

  /**
   * Handle tools/call request
   */
  private async handleToolsCall(request: JsonRpcRequest): Promise<void> {
    const params = request.params as {
      name: string;
      arguments?: Record<string, unknown>;
    };

    if (!params || !params.name) {
      this.transport.sendError(
        request.id,
        ErrorCodes.InvalidParams,
        'Missing tool name'
      );
      return;
    }

    const toolName = params.name;
    const toolArgs = params.arguments || {};

    // Validate tool exists
    const tool = tools.find(t => t.name === toolName);
    if (!tool) {
      this.transport.sendError(
        request.id,
        ErrorCodes.InvalidParams,
        `Unknown tool: ${toolName}`
      );
      return;
    }

    // If the default project isn't initialized yet, retry in case it was
    // initialized after the MCP server started (e.g. user ran codegraph init)
    this.retryInitIfNeeded();

    const result = await this.toolHandler.execute(toolName, toolArgs);

    this.transport.sendResult(request.id, result);
  }
}

